import re
from decimal import Decimal

# Largest amount accepted by parse_amount, in cents.
_MAX_CENTS = 100_000_000
_MAX_AMOUNT = Decimal("1000000.00")

# ASCII-only grammar: sign, digits, and an optional fractional part that
# requires digits on both sides of the decimal point.
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")


def _to_decimal(value):
    """Convert an accepted input to a Decimal without context rounding."""
    if isinstance(value, bool):
        raise ValueError("amount must be an int, a Decimal or a string")
    if isinstance(value, int):
        return Decimal(value)
    if isinstance(value, Decimal):
        return value
    if isinstance(value, str):
        if _AMOUNT_RE.fullmatch(value) is None:
            raise ValueError("invalid amount string: %r" % (value,))
        return Decimal(value)
    raise ValueError("unsupported amount type: %s" % type(value).__name__)


def _decimal_to_cents(amount):
    """Return exact integer cents for a finite Decimal, rejecting fractions."""
    _sign, digits, exponent = amount.as_tuple()
    coefficient = 0
    for digit in digits:
        coefficient = coefficient * 10 + digit
    if exponent >= -2:
        return coefficient * 10 ** (exponent + 2)
    extra = -2 - exponent
    if extra >= len(digits):
        if coefficient:
            raise ValueError("amount is not exactly representable in cents")
        return 0
    divisor = 10 ** extra
    if coefficient % divisor:
        raise ValueError("amount is not exactly representable in cents")
    return coefficient // divisor


def _cents_to_decimal(cents):
    """Build a Decimal with exponent -2 from an exact integer cent count."""
    return Decimal((0, tuple(int(digit) for digit in str(cents)), -2))


def _parse_amount_cents(value):
    """Validate ``value`` and return its exact number of cents."""
    amount = _to_decimal(value)
    if not amount.is_finite():
        raise ValueError("amount must be finite")
    if amount <= 0:
        raise ValueError("amount must be positive")
    if amount > _MAX_AMOUNT:
        raise ValueError("amount exceeds 1000000.00")
    cents = _decimal_to_cents(amount)
    if cents > _MAX_CENTS:
        raise ValueError("amount exceeds 1000000.00")
    return cents


def parse_amount(value):
    """Parse ``value`` into a positive Decimal with exactly two decimal places.

    Accepts integers (except bool), Decimal objects (exponent notation is
    fine) and strings that fully match ``[+-]?[0-9]+(?:\\.[0-9]+)?``.
    Values must be positive, no greater than 1000000.00 and exactly
    representable in cents; nonzero fractions of a cent are rejected.
    Arithmetic is context independent: the caller's decimal precision does
    not affect the result and the global decimal context is left untouched.
    """
    return _cents_to_decimal(_parse_amount_cents(value))


def format_amount(value):
    return format(value, ".2f")
